    #[test]
    fn test_single_pass_interpolation_no_recursive_expansion_and_alias() {
        let mut ctx = MessageContext::default();
        ctx.app = "Important Document {limit} - Notes".to_string();
        ctx.limit = "2h".to_string();
        ctx.rule_name = "Break Rule".to_string();

        // 1. {app} contains literal "{limit}" which must NOT be recursively expanded
        let result = ctx.interpolate("{app} - {limit}");
        assert_eq!(result, "Important Document {limit} - Notes - 2h");

        // 2. {app_name} alias for {app}
        let alias_result = ctx.interpolate("Active in {app_name} under {rule_name}");
        assert_eq!(alias_result, "Active in Important Document {limit} - Notes under Break Rule");

        // 3. Unknown placeholders and unclosed braces remain intact
        let unknown = ctx.interpolate("{app} [{unknown_tag}] {unclosed_tag");
        assert_eq!(unknown, "Important Document {limit} - Notes [{unknown_tag}] {unclosed_tag");
    }

    #[test]
    fn test_format_snooze_badge_sub_minute_and_multi_minute() {
        let now = Local::now();

        // < 60s remaining
        assert_eq!(format_snooze_badge(now + Duration::seconds(0), now), "Snoozed (0s)");
        assert_eq!(format_snooze_badge(now + Duration::seconds(1), now), "Snoozed (1s)");
        assert_eq!(format_snooze_badge(now + Duration::seconds(30), now), "Snoozed (30s)");
        assert_eq!(format_snooze_badge(now + Duration::seconds(59), now), "Snoozed (59s)");

        // >= 60s remaining
        assert_eq!(format_snooze_badge(now + Duration::seconds(60), now), "Snoozed (1m)");
        assert_eq!(format_snooze_badge(now + Duration::seconds(61), now), "Snoozed (2m)");
        assert_eq!(format_snooze_badge(now + Duration::seconds(119), now), "Snoozed (2m)");
        assert_eq!(format_snooze_badge(now + Duration::seconds(120), now), "Snoozed (2m)");
        assert_eq!(format_snooze_badge(now + Duration::minutes(5), now), "Snoozed (5m)");
        assert_eq!(format_snooze_badge(now + Duration::minutes(15), now), "Snoozed (15m)");
    }

    #[test]
    fn test_rule_message_fallback() {
        let mut rule = Rule::default_template(0);
        rule.action = RuleAction::ShowOverlay;
        assert!(rule_message_fallback(&rule).contains("Time for a Break"));

        rule.action = RuleAction::ShowNotification;
        rule.trigger = TriggerType::Period;
        assert!(rule_message_fallback(&rule).contains("Active for {session_duration}"));

        rule.trigger = TriggerType::Limit;
        assert!(rule_message_fallback(&rule).contains("Daily limit ({limit}) reached"));

        rule.action = RuleAction::LockWorkstation;
        assert_eq!(rule_message_fallback(&rule), "");
    }
